firestore.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /documents/{documentId} {
      // Anyone can read a document (encryption is handled client-side or verified later)
      allow read: if true;
      // Anyone can create a new document
      allow create: if true;
      // Only allow updates if they provide the correct passkeyHash (enforced in application logic or basic rules)
      // Since we don't have auth, we rely on the passkeyHash being sent and matching.
      allow update: if request.resource.data.passkeyHash == resource.data.passkeyHash;
      allow delete: if true; // Needed for burn-after-reading
    }
  }
}
